# פרק 12 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=12
TITLE='נטל ההוכחה ורף ההוכחה'
SUM=[' <p>שני מושגים דיוניים מרכזיים הקובעים <strong>מי</strong> צריך להוכיח ו<strong>באיזו עוצמה</strong>.</p> <h3>12.1 נטל ההוכחה</h3> <p><strong>מי</strong> נושא בחובה להוכיח טענה. הכלל: "<strong>המוציא מחברו עליו הראיה</strong>" — התובע/המאשים נושא בנטל. הנטל יכול <strong>לעבור</strong> בנסיבות מסוימות (חזקות).</p> <h3>12.2 רף ההוכחה</h3> <p><strong>עוצמת</strong> השכנוע הנדרשת. ב<strong>הליך אזרחי</strong> — <strong>מאזן ההסתברויות</strong> (למעלה מ-50%, "מתקבל יותר על הדעת מאשר לא"). ב<strong>הליך פלילי</strong> — <strong>מעבר לכל ספק סביר</strong> — רף גבוה בהרבה, הנגזר מחזקת החפות.</p> <h3>12.3 מדוע הפער</h3> <p>בפלילי מונח על הכף חירותו של אדם וכוח המדינה — ולכן "מוטב שיזוכו אשמים מאשר שיורשע חף".</p> <h3>12.4 נקודות מפתח למבחן</h3> <ul><li>נטל — מי מוכיח ("המוציא מחברו").</li><li>רף — אזרחי: מאזן הסתברויות; פלילי: מעבר לספק סביר.</li><li>הפער נובע מחזקת החפות.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('ע״פ 20/51 פודמסקי נ׳ היועץ המשפטי, פ״ד ה 1187', 'פסק דין מוקדם של בית המשפט העליון שעסק במבנה הנטלים בהליך הפלילי.', 'נקבע כי כשהתביעה הביאה ראיות לכאורה, עובר לנאשם רק הנטל לתת הסבר; בשום שלב אין עליו להוכיח את חפותו. אם נתן הסבר המתקבל על הדעת ובית המשפט אינו יכול להכריע אם הוא נכון — יש לזכותו מחמת הספק. חובת ההוכחה רובצת על התביעה ״עד סוף כל הסופות״.'), ('ע״פ 347/88 דמיאניוק נ׳ מדינת ישראל, פ״ד מז(4) 221', 'הנאשם הורשע בבית המשפט המחוזי בפשעים נגד העם היהודי ונגד האנושות בהיותו, לפי האישום, השומר ״איוון האיום״ במחנה ההשמדה טרבלינקה, ונגזר עליו עונש מוות.', 'בית המשפט העליון זיכה אותו, משום שראיות חדשות שהתגלו עוררו ספק סביר בשאלת זהותו כאותו אדם. פסק הדין כולל דיון מפורט בקושי להגדיר ספק סביר ומשמש דוגמה מובהקת לכך שחומרת העבירה אינה מורידה את הרף.'), ('ע״פ 6295/05 וקנין נ׳ מדינת ישראל (25.1.2007)', 'ערעור פלילי שבמסגרתו דן בית המשפט העליון בהרחבה במשמעותו של הספק הסביר.', 'ספק סביר צריך להיות רציני, הגיוני ובעל אחיזה במציאות; לא כל אפשרות רחוקה מצדיקה זיכוי. תמיהות הנוגעות לגרעין האירוע ולמעורבות הנאשם עשויות ליצור ספק סביר, ואילו פרטים שוליים שלא הובהרו אינם מונעים בהכרח הרשעה. הפסקאות שעוסקות בכך מצוטטות רבות בפסיקה מאוחרת.'), ('ע״פ 7220/05 נימר נ׳ מדינת ישראל', 'ערעור פלילי שבו נדרש בית המשפט העליון ליסודות רף ההוכחה בפלילים.', 'השופטת פרוקצ׳יה הדגישה שהחובה להוכיח אשמה מעבר לספק סביר נגזרת מעקרונות חוקתיים של חירות וכבוד האדם, שחזקת החפות ועקרון הספק הסביר משלימים זה את זה, ושהרף הגבוה הוא כלי מרכזי נגד הרשעות שווא, על בסיס העיקרון שעדיף שאשם יזוכה מאשר שזכאי יורשע.'), ('ע״פ 3372/11 קצב נ׳ מדינת ישראל (10.11.2011)', 'ערעור של נשיא המדינה לשעבר על הרשעתו בעבירות מין. ההגנה טענה שאירועי ״המעטפת״ ושאלות על מהימנות המתלוננת מקימים ספק סביר.', 'הערעור נדחה. נקבע שגרסה חלופית יוצרת ספק סביר רק אם היא סבירה ולא רק אפשרית, ושיש לבחון אם הראיות מעוררות ספק בגרעין האירוע. בית המשפט הדגיש שהמערער אינו מורשע משום שהוא שקרן, אלא משום שעדות המתלוננת נמצאה מהימנה וחומר הראיות לא העלה ספק סביר.'), ('ע״א 475/81 זיקרי נ׳ ״כלל״ חברה לביטוח בע״מ, פ״ד מ(1) 589', 'תביעה של מבוטח נגד חברת ביטוח, שבה הועלתה טענה בעלת אופי פלילי נגד המבוטח, והתעוררה השאלה מהו רף ההוכחה הנדרש.', 'נחלקו הדעות: השופט בך סבר שיש רף ביניים לטענות המטילות על הצד השני סטיגמה של עבירה חמורה; השופט ברק סבר שאין ליצור רף שלישי, אלא שהרף נשאר מאזן ההסתברויות, וכמות הראיות ומשקלן מותאמים לחומרת הטענה. המסקנה המעשית: טענה כזו דורשת ראיות כבדות משקל.')]
QS=[{'q': 'מה ההבדל בין נטל השכנוע לנטל הבאת הראיות?', 'o': ['נטל הבאת הראיות קבוע ונטל השכנוע עובר בין הצדדים', 'נטל השכנוע חל רק בפלילים ונטל הבאת הראיות רק באזרחי', 'נטל השכנוע קובע מי מפסיד אם בית המשפט לא שוכנע, ונטל הבאת הראיות קובע מי צריך להביא ראיות בשלב מסוים של המשפט', 'אין הבדל; אלה שני שמות לאותו נטל'], 'c': 2, 'e': 'נכון. נטל השכנוע הוא הנטל המכריע בסוף; נטל הבאת הראיות הוא הנטל הטקטי שעובר מצד לצד.'}, {'q': 'מהו רף ההוכחה בהליך אזרחי רגיל?', 'o': ['ראיות ברורות ומשכנעות בכל מקרה', 'ודאות מוחלטת', 'מעבר לספק סביר', 'מאזן ההסתברויות: הגרסה מסתברת יותר מהגרסה שכנגד'], 'c': 3, 'e': 'נכון. בהליך אזרחי די שהגרסה של הנושא בנטל מסתברת יותר, כלומר מעל 50%.'}, {'q': 'מה קובע ס׳ 34כב(א) לחוק העונשין?', 'o': ['לא יישא אדם באחריות פלילית לעבירה אלא אם כן היא הוכחה מעבר לספק סביר', 'אין עבירה ואין עונש עליה אלא אם כן נקבעו בחוק', 'על הנתבע הראיה שלא היתה התרשלות', 'חזקה על מעשה שנעשה בתנאים שאין בהם סייג לאחריות פלילית'], 'c': 0, 'e': 'נכון. זהו העיגון החקוק של רף הספק הסביר.'}, {'q': 'נאשם בתקיפה טוען להגנה עצמית. הראיות מותירות ספק סביר שמא אכן פעל להגנה עצמית, אך הוא לא הוכיח זאת במאזן הסתברויות. מה הדין?', 'o': ['הוא יורשע, כי ס׳ 34ה מניח שאין סייג', 'בית המשפט יפסוק פשרה', 'הסייג יחול והוא יזוכה, כי לפי ס׳ 34כב(ב) די בספק סביר שלא הוסר', 'הוא יורשע, כי לא הוכיח את ההגנה במאזן הסתברויות'], 'c': 2, 'e': 'נכון. התעורר ספק סביר שמא קיים סייג והספק לא הוסר — הסייג חל.'}, {'q': 'מה המשמעות של ס׳ 34ה לחוק העונשין?', 'o': ['שכל נאשם נהנה מסייג אוטומטית', 'שנקודת המוצא היא שלא התקיים סייג לאחריות, ולכן הנאשם צריך להעלות אותו ולהצביע על ראיות התומכות בו', 'שהנאשם חייב להוכיח את חפותו', 'שהתביעה פטורה מלהוכיח את יסודות העבירה'], 'c': 1, 'e': 'נכון. החזקה מטילה על הנאשם נטל להעלות את הסייג, אך לפי ס׳ 34כב(ב) די שיעורר ספק סביר.'}, {'q': 'תובעת בתביעה אזרחית הביאה ראיות שמבססות לכאורה את טענתה, והנתבע בחר לא להעיד ולא להביא ראיות. מה הסיכון של הנתבע?', 'o': ['התביעה תידחה אוטומטית', 'אין סיכון, כי נטל השכנוע תמיד על התובעת', 'בית המשפט חייב למנות לו עורך דין', 'נטל הבאת הראיות עבר אליו, ואם לא יביא ראיות בית המשפט עלול לקבוע את העובדות לחובתו'], 'c': 3, 'e': 'נכון. זהו הנטל הטקטי: הכדור עבר לנתבע, והימנעות מהבאת ראיות עלולה להכריע את התיק נגדו.'}, {'q': 'בהליך אזרחי, בתום שמיעת הראיות, בית המשפט קובע שהגרסאות של שני הצדדים שקולות לחלוטין. מה התוצאה לגבי העובדה שבמחלוקת?', 'o': ['בית המשפט יורה על משפט חוזר', 'הצד שנושא בנטל השכנוע מפסיד בעניין זה', 'הצד הנתבע מפסיד תמיד', 'בית המשפט יחלק את הסכום באמצע'], 'c': 1, 'e': 'נכון. כשהמאזניים מאוזנים, מי שנושא בנטל השכנוע לא הרים אותו ולכן מפסיד.'}, {'q': 'אדם נפגע ממעלית בבניין שבשליטה מלאה של חברת ניהול. הוא אינו יודע מה גרם לתקלה, והתאונה מתיישבת יותר עם התרשלות מאשר עם זהירות. מה ההשלכה?', 'o': ['החברה אחראית אוטומטית ללא אפשרות להתגונן', 'לפי ס׳ 41 לפקודת הנזיקין עובר לחברה הנטל להוכיח שלא התרשלה', 'הנפגע חייב להוכיח בדיוק מה הייתה התקלה', 'התביעה תידחה בשל היעדר ראיות'], 'c': 1, 'e': 'נכון. שלושת התנאים של ״הדבר מעיד על עצמו״ מתקיימים, ולכן הנטל עובר לנתבע.'}, {'q': 'נהג זוכה בבית משפט פלילי מעבירה של גרימת חבלה ברשלנות מחמת הספק. הנפגע תובע אותו בנזיקין על אותה תאונה. מה נכון?', 'o': ['התביעה יכולה להתקבל, כי הרף האזרחי נמוך יותר ואותן ראיות עשויות לעמוד בו', 'בית המשפט האזרחי חייב לקבל את קביעות בית המשפט הפלילי לטובת הנהג', 'התביעה תידחה בהכרח, כי הנהג זוכה', 'התביעה תתקבל בהכרח, כי היה כתב אישום'], 'c': 0, 'e': 'נכון. מאזן ההסתברויות נמוך מספק סביר, ולכן אין סתירה בין זיכוי בפלילים לחיוב בנזיקין.'}, {'q': 'מהי ההצדקה המרכזית לכך שהרף בפלילים גבוה מהרף באזרחי?', 'o': ['שבמשפט הפלילי אין עדים', 'שבפלילים הטעויות אינן סימטריות: הרשעת חף מפשע חמורה בהרבה מזיכוי של אשם', 'שהנאשמים תמיד דוברי אמת', 'שהמשפט הפלילי פחות חשוב'], 'c': 1, 'e': 'נכון. הרף הגבוה מטיל את סיכון הטעות על המדינה, בשל חומרת הרשעת שווא ופערי הכוחות.'}, {'q': 'חברת ביטוח מסרבת לשלם למבוטח בטענה שהוא עצמו הצית את עסקו. לפי הלכת זיקרי, מה נדרש מהמבטחת?', 'o': ['להוכיח את ההצתה מעבר לספק סביר', 'המבוטח צריך להוכיח שלא הצית', 'די בחשד בלבד', 'להביא ראיות כבדות משקל, מעבר לרגיל בתיק אזרחי, להוכחת הטענה'], 'c': 3, 'e': 'נכון. בין לפי גישת בך (רף ביניים) ובין לפי גישת ברק (התאמת משקל הראיות), דרושות ראיות כבדות משקל.'}, {'q': 'במה נחלקו השופטים בך וברק בעניין זיקרי?', 'o': ['האם חברות ביטוח רשאיות לסרב לשלם', 'האם ההליך האזרחי כפוף לחוק העונשין', 'האם קיים רף הוכחה שלישי (ביניים) לטענות בעלות אופי פלילי בהליך אזרחי, או שהרף אחד ורק משקל הראיות משתנה', 'האם יש לבטל את רף הספק הסביר'], 'c': 2, 'e': 'נכון. בך תמך ברף ביניים; ברק התנגד לרף שלישי והעדיף התאמה של כמות הראיות ומשקלן.'}, {'q': 'מה נקבע בעניין פודמסקי לגבי הנטל המוטל על הנאשם?', 'o': ['שנטל השכנוע עובר לנאשם לאחר פרשת התביעה', 'שהנאשם חייב להעיד בכל מקרה', 'שכשהתביעה הביאה ראיות לכאורה, על הנאשם רק לתת הסבר; אם ההסבר סביר ובית המשפט אינו יכול להכריע — יש לזכותו', 'שעל הנאשם להוכיח את חפותו מעבר לספק סביר'], 'c': 2, 'e': 'נכון. חובת ההוכחה רובצת על התביעה ״עד סוף כל הסופות״; לנאשם עובר רק נטל טקטי.'}, {'q': 'מה קבע בית המשפט העליון בעניין דמיאניוק?', 'o': ['שהרף בפלילים הוא מאזן הסתברויות', 'שהנאשם זוכה משום שראיות חדשות עוררו ספק סביר בשאלת זהותו כמבצע', 'שהנאשם הורשע מעבר לכל ספק', 'שבעבירות חמורות במיוחד ניתן להסתפק ברף נמוך יותר'], 'c': 1, 'e': 'נכון. בית המשפט העליון זיכה את הנאשם בשל ספק סביר בזהותו, למרות הרשעתו בערכאה הראשונה.'}, {'q': 'לפי הפסיקה (וקנין), איזה ספק יכול להצדיק זיכוי?', 'o': ['כל ספק, גם דמיוני', 'ספק רציני והגיוני בעל אחיזה במציאות, במיוחד כשהוא נוגע לגרעין האירוע', 'רק ספק שהנאשם הוכיח במאזן הסתברויות', 'רק ספק שהתביעה הודתה בו'], 'c': 1, 'e': 'נכון. וקנין מבחין גם בין תמיהות שנוגעות לליבת האירוע לבין פרטים שוליים.'}, {'q': 'הנאשם הציג גרסה חלופית שתיאורטית אפשרית, אך אינה מתיישבת עם רוב הראיות ואינה סבירה. האם היא יוצרת ספק סביר?', 'o': ['כן, כל גרסה אפשרית יוצרת ספק סביר', 'לא בהכרח: גרסה חלופית יוצרת ספק סביר רק אם היא סבירה ולא רק אפשרית', 'לא, כי נאשם אינו רשאי להציג גרסה חלופית', 'כן, אם הנאשם העיד עליה בשבועה'], 'c': 1, 'e': 'נכון. כך הובהר, למשל, בעניין קצב: גרסאות חלופיות מבססות ספק רק כשהן סבירות.'}, {'q': 'בגזר הדין טוענת התביעה לנסיבה מחמירה הקשורה בביצוע העבירה, וההגנה טוענת לנסיבה מקילה. לפי ס׳ 40י(ג) לחוק העונשין, מה הרף לכל אחת?', 'o': ['מחמירה — מעבר לספק סביר; מקילה — ברמת ההוכחה של משפט אזרחי', 'מחמירה — מאזן הסתברויות; מקילה — ספק סביר', 'שתיהן מעבר לספק סביר', 'שתיהן במאזן הסתברויות'], 'c': 0, 'e': 'נכון. החוק מחיל רף גבוה על מה שפועל לחובת הנאשם ורף אזרחי על מה שפועל לטובתו.'}, {'q': 'מה הקשר בין חזקת החפות לבין עקרון הספק הסביר, לפי הפסיקה?', 'o': ['הם משלימים זה את זה: החזקה היא נקודת המוצא, והספק הסביר הוא אמת המידה לשאלה אם היא הופרכה', 'הספק הסביר מבטל את חזקת החפות', 'אין ביניהם קשר', 'חזקת החפות חלה רק לפני הגשת כתב אישום'], 'c': 0, 'e': 'נכון. כך הוסבר, למשל, בעניין נימר.'}, {'q': 'בתביעת עובד לשכר על שעות נוספות, המעסיק לא ניהל רישומי נוכחות כנדרש. מה הרעיון שעומד מאחורי העברת הנטל למעסיק במצבים כאלה?', 'o': ['שאין לאפשר לצד ליהנות מכך שהמידע בשליטתו או שהוא עצמו גרם לחסר הראייתי', 'שהמעסיק תמיד משקר', 'שהעובד פטור תמיד מכל הוכחה', 'שבדיני עבודה אין נטל הוכחה'], 'c': 0, 'e': 'נכון. זה ההיגיון המשותף לחזקות ולהוראות שמעבירות נטל: הצד שמחזיק במידע או שגרם לחסר נושא בסיכון.'}, {'q': 'מה פירוש הכלל ״המוציא מחברו עליו הראיה״?', 'o': ['שהנתבע תמיד נושא בנטל', 'שבית המשפט מוכיח את העובדות בעצמו', 'שהצד העשיר יותר נושא בנטל', 'שמי שמבקש לקבל סעד משנה את המצב הקיים ועליו להוכיח את טענתו'], 'c': 3, 'e': 'נכון. זהו הכלל הבסיסי במשפט האזרחי: מי שתובע — מוכיח, וכל צד מוכיח את טענותיו.'}]
